// The new frontend build in a real browser against the scratch server on :8010.
const fs = require("fs");
const path = require("path");
const { chromium } = require("playwright-core");
const dist = process.argv[2];
const ORIGIN = "http://dtm.test";
const API = "http://127.0.0.1:8010";
const MIME = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".png": "image/png", ".ico": "image/x-icon" };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ channel: "chrome", headless: true });
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const problems = [];
  const calls = [];
  const attach = async (page) => {
    page.on("pageerror", (e) => problems.push("pageerror: " + e.message));
    page.on("console", (m) => { if (m.type() === "error") problems.push("console: " + m.text()); });
    await page.route("**/*", async (route) => {
      const req = route.request();
      const url = new URL(req.url());
      if (url.pathname.startsWith("/api/")) {
        calls.push(`${req.method()} ${url.pathname}`);
        const res = await route.fetch({ url: API + url.pathname + url.search });
        return route.fulfill({ response: res });
      }
      let file = path.join(dist, url.pathname);
      if (url.pathname.endsWith("/")) file = path.join(file, "index.html");
      if (!fs.existsSync(file)) return route.fulfill({ status: 404, body: "" });
      await route.fulfill({ body: fs.readFileSync(file), contentType: MIME[path.extname(file)] || "application/octet-stream" });
    });
  };
  const lab = await context.newPage();
  await attach(lab);
  await lab.goto(ORIGIN + "/lab/");
  await lab.waitForSelector("text=Send 25 now");
  const total = async () => (await lab.locator(".counter-value").allInnerTexts()).join(",");
  const before = await total();
  await lab.click("text=Send 25 now");
  await lab.waitForFunction((b) => [...document.querySelectorAll(".counter-value")].map((e) => e.innerText).join(",") !== b, before, { timeout: 15000 });
  console.log("Lab: 'Send 25 now' updated the counters:", before, "->", await total());
  await lab.click(".scenario-row-id:text('DS-01')");
  await lab.click("text=Inject fault");
  await lab.waitForSelector("text=Open INC-0001", { timeout: 30000 });
  console.log("Lab: injected DS-01, page shows 'Open INC-0001'");

  const con = await context.newPage();
  await attach(con);
  await con.goto(ORIGIN + "/#/incidents/INC-0001");
  await con.waitForSelector(".incident-hero");
  console.log("Console: incident page shows", (await con.locator(".incident-hero h1").innerText()).replace(/\s+/g, " "));
  await con.evaluate(() => { location.hash = "/incidents"; });
  await con.waitForSelector("table");
  await con.evaluate(() => { location.hash = "/overview"; });
  await con.waitForSelector(".kpis");
  console.log("Console: overview trust badge:", (await con.locator(".topbar-right .badge").first().innerText()));
  await con.evaluate(() => { location.hash = "/audit"; });
  await con.waitForSelector("text=entries");
  await sleep(6000);

  await lab.bringToFront();
  lab.once("dialog", (d) => d.dismiss());
  await lab.click("text=Reset to baseline");
  await sleep(300);
  if (await lab.locator("text=Click again to reset").count()) await lab.click("text=Click again to reset");
  await lab.waitForSelector("text=Clean baseline", { timeout: 30000 });
  console.log("Lab: reset, page shows 'Clean baseline'");
  const posts = calls.filter((c) => c.startsWith("POST"));
  console.log("POSTs made:", posts.join(", "));
  console.log("problems:", problems.length ? problems : "none");
  await browser.close();
})().catch((err) => { console.error("FAILED", err.message.split("\n")[0]); process.exit(1); });
